parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "respuesta": {
      "type": "object",
      "properties": {
        "mensaje": { "type": "string", "description": "Mensaje final para el promotor" }
      },
      "required": ["mensaje"]
    },
    "reporte_interaccion": {
      "type": "object",
      "properties": {
        "usuario_promotor": { "type": "string", "description": "Nombre del promotor, o Sin identificar" },
        "tipo_consulta": { "type": "string" },
        "herramientas_utilizadas": { "type": "array", "items": { "type": "string" } },
        "estado_solicitud": { "type": "string" },
        "detalle_breve": { "type": "string" },
        "limitaciones": { "type": "string", "description": "Limitaciones reales, o Ninguna" }
      },
      "required": ["usuario_promotor", "tipo_consulta", "herramientas_utilizadas", "estado_solicitud", "detalle_breve", "limitaciones"]
    }
  },
  "required": ["respuesta", "reporte_interaccion"]
}
